class TranslationRequest:
    def __init__(self, text: str, source_language: str, target_language: str):
        if not isinstance(text, str) or not text:
            raise ValueError("Text must be a non-empty string.")
        if not isinstance(source_language, str) or not source_language:
            raise ValueError("Source language must be a non-empty string.")
        if not isinstance(target_language, str) or not target_language:
            raise ValueError("Target language must be a non-empty string.")

        self.text = text
        self.source_language = source_language
        self.target_language = target_language

    def to_dict(self):
        return {
            "text": self.text,
            "source_language": self.source_language,
            "target_language": self.target_language,
        }

class TranslationResponse:
    def __init__(self, translated_text: str):
        if not isinstance(translated_text, str):
            raise ValueError("Translated text must be a string.")
        self.translated_text = translated_text

    def to_dict(self):
        return {"translated_text": self.translated_text}

def normalize_text(text: str) -> str:
    """
    Performs basic normalization on the input text.
    For example, strips leading/trailing whitespace.
    """
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    return text.strip()

import os
from google.cloud import translate_v3beta1 as translate

class TranslationClient:
    def __init__(self):
        self.project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
        if not self.project_id:
            raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")
        self.client = translate.TranslationServiceClient()

    def translate_text(self, text, target_language_code, source_language_code=None):
        parent = f"projects/{self.project_id}"

        config = {
            "source_language_code": source_language_code,
            "target_language_code": target_language_code,
        }

        response = self.client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "mime_type": "text/plain",  # Mime types: "text/plain", "text/html"
                "model": "projects/project-number/locations/global/models/general/nmt", # General purpose model
                "target_language_code": target_language_code,
            }
        )

        translated_text = ""
        for translation in response.translations:
            translated_text += translation.translated_text
        return translated_text
